package checks;
import java.util.*;import net.minecraft.world.item.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.client.Minecraft;import com.raiiiden.warborn.common.item.*;import com.raiiiden.warborn.common.util.*;import com.raiiiden.warborn.client.util.NvgClient2;import com.raiiiden.warborn.client.shader.*;import com.raiiiden.warborn.client.network.ClientBatteryUpdateHandler;import com.raiiiden.warborn.common.network.*;import com.raiiiden.warborn.common.event.HelmetBatteryTickHandler;
public class NvgChecks {
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 public static class Tag{public Map<String,Object> values=new HashMap<>();public int getInt(String s){return ((Number)values.getOrDefault(s,0)).intValue();}public void putInt(String s,int n){values.put(s,n);}public void remove(String s){values.remove(s);}}
 public static class World{public long getGameTime(){return 1;}public boolean isClientSide(){return false;}}
 public static class Renderer{public Object effect;public Object currentEffect(){return effect;}}
 static ItemStack helmet(WBArmorItem item,String mode,int energy){ItemStack s=new ItemStack(item);s.goggles=new ItemStack(new GogglesItem(mode));s.battery=new ItemStack(new NVGBatteryItem());s.battery.tag.putInt("BatteryEnergy",energy);return s;}
 static String active(ServerPlayer p){return ClientVisionState.getActive(p.uuid);}
 static void tick(){NvgClient2.tick(null);}
 public static void main(String[]a){
  Minecraft mc=Minecraft.getInstance();ServerPlayer p=new ServerPlayer();mc.player=p;mc.level=p.world;WBArmorItem item=new WBArmorItem();p.helmet=helmet(item,"nvg",50000);tick();ok(active(p).equals("nvg"),"lowered visor auto enables green vision");ok(com.raiiiden.warborn.client.event.ModKeybindings.TOGGLE_HELMET_TOP.getKey().getValue()==78,"old H binding migrated to N");ok(com.raiiiden.warborn.client.event.ModKeybindings.TOGGLE_SPECIAL_VISION.getKey().getValue()==-1,"old N standalone binding removed");int packets=ModNetworking.packets.size(),changes=ShaderRegistry.INSTANCE.calls;for(int i=0;i<50;i++)tick();ok(ModNetworking.packets.size()==packets&&ShaderRegistry.INSTANCE.calls==changes,"stable visor does not spam packets or reload shader");
  ShaderRegistry.INSTANCE.enabled.put("nvg",false);tick();ok(ShaderRegistry.INSTANCE.enabled.get("nvg")&&active(p).equals("nvg"),"lost shader enable flag repaired after external effect");
  p.helmet.open=true;tick();ok(active(p).isEmpty(),"raising visor disables special vision");p.helmet.open=false;tick();ok(active(p).equals("nvg"),"lowering enables vision without second key");
  p.helmet=helmet(new WBArmorItem(),"thermal_white",30000);tick();ok(active(p).equals("thermal_white"),"switch helmet immediately selects new vision");ok(!ShaderRegistry.INSTANCE.enabled.get("nvg")&&ShaderRegistry.INSTANCE.enabled.get("twvg"),"old shader disabled before new shader");
  p.helmet=helmet(item,"digital",20000);tick();p.helmet=helmet(item,"thermal_black",20000);tick();ok(active(p).equals("thermal_black"),"same item model with different installed goggles switches correctly");
  ClientBatteryUpdateHandler.handle(0);NvgClient2.empty();ok(active(p).isEmpty(),"empty battery disables mode");for(int i=0;i<25;i++)tick();ok(active(p).isEmpty()&&ClientBatteryUpdateHandler.cached==0,"empty battery cannot reactivate against stale item NBT");p.helmet=helmet(item,"nvg",50000);tick();ok(active(p).equals("nvg"),"new helmet clears previous empty battery cache");
  ShaderRegistry registry=ShaderRegistry.INSTANCE;registry.active("nvg");mc.gameRenderer.effect=new Object();Object expected=mc.gameRenderer.effect;NvgClient2.loaded(registry);NvgClient2.recover(registry);ok(registry.active().equals("nvg"),"healthy shader kept");mc.gameRenderer.effect=null;NvgClient2.recover(registry);ok(registry.active()==null&&active(p).equals("nvg"),"missing shader invalidates renderer cache without disabling vision intent");registry.active("nvg");mc.gameRenderer.effect=expected;NvgClient2.loaded(registry);mc.gameRenderer.effect=new Object();NvgClient2.recover(registry);ok(registry.active()==null,"replacement hurt shader invalidates stale NVG cache");registry.active("nvg");NvgClient2.loaded(registry);NvgClient2.recover(registry);ok(registry.active().equals("nvg"),"recovered chain not reloaded every frame");registry.active("custom_shader");mc.gameRenderer.effect=new Object();NvgClient2.recover(registry);ok(registry.active().equals("custom_shader"),"unrelated shader management preserved");
  p.helmet.open=true;ok(NvgLink2.authorize("nvg",p).isEmpty(),"server rejects NVG through raised visor");p.helmet.open=false;ok(NvgLink2.authorize("thermal",p).equals("nvg"),"server uses real installed goggles, not requested client type");
  ItemStack old=p.helmet;HelmetBatteryTickHandler.helmetReference.put(p.uuid,old);HelmetBatteryTickHandler.batteryEnergyCache.put(p.uuid,1234);HelmetBatteryTickHandler.nvgActiveMap.put(p.uuid,"nvg");p.helmet=helmet(item,"digital",25000);NvgLink2.server(p);ok(old.battery.tag.getInt("BatteryEnergy")==1234,"old battery receives its cached energy on swap");ok(p.helmet.battery.tag.getInt("BatteryEnergy")==25000&&!HelmetBatteryTickHandler.batteryEnergyCache.containsKey(p.uuid),"new battery does not inherit old cache");ok(HelmetBatteryTickHandler.nvgActiveMap.get(p.uuid).equals("digital"),"server mode follows new goggles");
  p.helmet.open=true;NvgLink2.server(p);ok(!HelmetBatteryTickHandler.nvgActiveMap.containsKey(p.uuid),"server stops drain when visor raised");p.helmet.open=false;p.helmet.battery.tag.putInt("BatteryEnergy",0);NvgLink2.server(p);ok(!HelmetBatteryTickHandler.nvgActiveMap.containsKey(p.uuid),"empty battery cannot auto enable on server");
  int energy=50000;for(int second=1;second<=900;second++){energy-=NvgSupport33.drain(999,p);if(second<900)ok(energy>0,"battery still powered before 15 minutes");}ok(energy==0,"original exact fifteen-minute drain retained");
  p.helmet=ItemStack.EMPTY;tick();ok(active(p).isEmpty(),"unequipping removes all special vision");mc.player=null;mc.level=null;tick();mc.player=p;mc.level=new World();p.helmet=helmet(item,"thermal",10000);tick();ok(active(p).equals("thermal"),"reconnect clears stale world identity");
  p.helmet.visor=false;tick();ok(active(p).isEmpty(),"helmet without physical visor uses manual intent");NvgClient2.key(new Object());ok(active(p).equals("thermal"),"same N key supports non-visor modded helmets");NvgClient2.key(new Object());ok(active(p).isEmpty(),"non-visor second press disables vision");
  System.out.println("NVG_LINK_CHECKS="+checks);
 }
}
